package solution

func MultisetOverlap(left []int, right []int) []int {
    leftCopy := make([]int, len(left))
    copy(leftCopy, left)
    rightCopy := make([]int, len(right))
    copy(rightCopy, right)

    leftIdx := 0
    rightIdx := 0
    result := make([]int, 0)

    for leftIdx < len(leftCopy) && rightIdx < len(rightCopy) {
        if leftCopy[leftIdx] == rightCopy[rightIdx] {
            // Check if there are more occurrences of this value in right
            if rightIdx+1 < len(rightCopy) && rightCopy[rightIdx+1] == rightCopy[rightIdx] {
                // Use one occurrence
                result = append(result, leftCopy[leftIdx])
                leftIdx++
                rightIdx++
            } else {
                // No more occurrences of this value in right, consume the rest of left
                for leftIdx < len(leftCopy) {
                    result = append(result, leftCopy[leftIdx])
                    leftIdx++
                }
                break
            }
        } else {
            // Values differ, consume the smaller one
            if leftCopy[leftIdx] < rightCopy[rightIdx] {
                leftIdx++
            } else {
                rightIdx++
            }
        }
    }

    return result
}

